const assert = require('node:assert/strict');
const Version = require('../js/prototype-project-version');

assert.equal(Version.projectCode({ salesCompanyCode: 'BJ' }, '2610', 1), 'BJ-2610-001');
assert.throws(() => Version.projectCode({ salesCompany: '北京销售公司' }, '2610', 1), /不能根据公司名称猜测/);
assert.equal(Version.nextUnitSequence({ units: [{ no: 'AHU-001-A', sequenceNo: '001' }, { no: 'AHU-003', sequenceNo: '003' }] }), '002');
assert.throws(() => Version.nextUnitSequence({ units: [{ no: 'legacy-001' }] }), /确认编号中的三位/);
assert.equal(Version.inferSequenceNo('V-BJ2609-F6-001D-TE'), '001');
assert.equal(Version.inferSequenceNo('V-001-2609-002'), null, 'multiple three-digit candidates require user selection');
assert.deepEqual(Version.nextEquipmentNumber([{ no: 'V-BJ2609-F6-001D-TE', sequenceNo: '001' }]), { no: 'V-BJ2609-F6-002', sequenceNo: '002' });
assert.deepEqual(Version.nextEquipmentNumber([], [{ no: 'V-BJ2609-F6-001D-TE', sequenceNo: '001' }]), { no: 'V-BJ2609-F6-002', sequenceNo: '002' }, 'deleted equipment numbers remain reserved and legacy D/T-E are not copied');
assert.deepEqual(Version.nextEquipmentNumber([{ no: 'V-BJ2609-F6-005', sequenceNo: '005' }]), { no: 'V-BJ2609-F6-006', sequenceNo: '006' }, 'new unit numbering continues after the entered number');
assert.deepEqual(Version.nextEquipmentNumber([{ no: 'V-BJ2609-F6-001', sequenceNo: '001' }, { no: 'V-BJ2609-F6-003', sequenceNo: '003' }], [{ no: 'V-BJ2609-F6-002', sequenceNo: '002' }]), { no: 'V-BJ2609-F6-004', sequenceNo: '004' }, 'deleted historical numbers remain included in the sequential maximum');
assert.equal(Version.nextRevision('V-BJ2609-F6-001D-TE', ['V-BJ2609-F6-001D-TE', 'V-BJ2609-F6-001D-A-TE']), 'V-BJ2609-F6-001-E-TE');
assert.throws(() => Version.nextRevision('AHU-001', ['AHU-001-Z']), /尚未确认/);
assert.equal(Version.nextRevision('AHU-001-A', []), 'AHU-001-B', 'revision never moves backward when history is incomplete');
assert.equal(Version.nextRevision({ no:'AHU-001D', revisionNo:'D' }), 'AHU-001-E', 'legacy D marker advances to E');
assert.equal(Version.nextRevision({ no:'AHU-001', revisionNo:'E' }), 'AHU-001-F', 'revision E is explicit and advances to F');
assert.equal(Version.nextRevision({ no:'AHU-001', revisionNo:'S', nonstandardFlag:true }), 'AHU-001-T-T', 'revision S can advance to T while retaining independent T flag');
assert.equal(Version.nextRevision({ no:'AHU-001-T', revisionNo:'T', nonstandardFlag:true }), 'AHU-001-U-T', 'revision T advances to U without mistaking the independent T flag');
assert.equal(Version.nextRevision({ no:'AHU-001', revisionNo:'E', nonstandardFlag:true, parameterAdjustmentFlag:true }), 'AHU-001-F-TE', 'T and E flags survive revision changes independently');
assert.equal(Version.nextRevision({ no:'AHU-001-T', nonstandardFlag:true }, [], { currentFlags:'T', flags:'' }), 'AHU-001-A', 'removing an old T flag does not reinterpret T as revision');
assert.equal(Version.nextRevision({ no:'AHU-001-A-TE', revisionNo:'A', nonstandardFlag:true, parameterAdjustmentFlag:true }, [], { currentRevision:'A', currentFlags:'TE', flags:'T' }), 'AHU-001-B-T', 'removing E preserves the existing revision sequence');
assert.equal(Version.nextRevision({ no:'AHU-001-B-T', revisionNo:'B', nonstandardFlag:true }, [], { currentRevision:'B', currentFlags:'T', flags:'' }), 'AHU-001-C', 'removing T after E removal preserves the revision sequence');
assert.throws(() => Version.nextRevision('AHU-001-E', []), /歧义/);
const previous = Version.freezeExport({ code: 'BJ-2610-001', units: [{ unitId: 'u1', unitLineageId: 'u1', no: '001', airflow: 1 }] });
const next = Version.freezeExport({ code: 'BJ-2610-001', units: [{ unitId: 'u1', unitLineageId: 'u1', no: '001', airflow: 2 }, { unitId: 'u2', unitLineageId: 'u2', no: '002' }] });
const diff = Version.compareExports(previous, next);
assert.equal(diff.overview.added, 1);
assert.equal(diff.overview.modified, 1);
assert.equal(diff.units.length, 2);
assert.equal(diff.units.find(unit => unit.unitNo === '001').changes.parameters[0].before, 1);
const addedWithTechnicalFields = Version.compareExports(null, Version.freezeExport({ code: 'P', units: [{ unitId: 'internal-id', unitLineageId: 'internal-lineage', no: '003', lastConfirmedFingerprint: 'secret-hash', usedUnitNumbers: [{ no: '003', unitId: 'internal-id' }], revisionNo: 'B', pendingRecalculation: false, name: '新增机组', segments: [{ id: 'segment-id', name: '送风段' }] }] }));
assert.equal(JSON.stringify(addedWithTechnicalFields.fields).includes('secret-hash'), false, 'added-unit records omit internal fingerprints and identifiers');
assert.equal(JSON.stringify(addedWithTechnicalFields.fields).includes('internal-id'), false, 'added-unit records omit technical IDs');
assert.equal(addedWithTechnicalFields.fields.some(field => field.path.includes('name') && field.after === '新增机组'), true, 'added-unit records retain readable business fields');
const deletedWithTechnicalFields = Version.compareExports(Version.freezeExport({ code: 'P', units: [{ unitId: 'internal-id', unitLineageId: 'internal-lineage', no: '003', lastConfirmedFingerprint: 'secret-hash', name: '待删除机组' }] }), Version.freezeExport({ code: 'P', units: [] }));
assert.equal(JSON.stringify(deletedWithTechnicalFields.fields).includes('secret-hash'), false, 'deleted-unit records omit internal fingerprints');
assert.equal(JSON.stringify(deletedWithTechnicalFields.fields).includes('internal-id'), false, 'deleted-unit records omit technical IDs');
assert.equal(deletedWithTechnicalFields.fields.some(field => field.path.endsWith('.name') && field.before === '待删除机组'), true, 'deleted-unit records retain readable business fields');
const unchanged = Version.compareExports(previous, Version.freezeExport({ ...JSON.parse(JSON.stringify(previous.snapshot)), modifiedAt: 'changed', versionId: 'new-version', units: [{ ...previous.snapshot.units[0], unitId: 'new-id', modifiedAt: 'changed' }] }));
assert.equal(unchanged.units.length, 0, 'technical metadata changes do not appear as engineering differences');
console.log('通过：项目编号校验、机组号补位、修订顺延和逐版快照差异正常。');
